import sys

def main():
    import sys
    s = sys.stdin.read().strip()
    n = len(s)
    t = ['0'] * n
    max_lis = [1] * n
    dp = [0] * (n + 1)

    for i in range(n):
        dp[i] = 1
        for j in range(i):
            if s[i] >= s[j]:
                dp[i] = max(dp[i], dp[j] + 1)
        max_lis[i] = dp[i]

    for i in range(n - 1, -1, -1):
        if max_lis[i] == dp[i]:
            t[i] = '1'
            dp[i] -= 1

    print(''.join(t))

if __name__ == "__main__":
    main()
